<script setup lang="ts">
import {ref} from 'vue'
const targets=[{id:'delivery',label:'Delivery',body:'Sample delivery window: two working days.'},{id:'returns',label:'Returns',body:'Sample returns note: keep the packaging.'}]
const opened=ref<string[]>([]),direction=ref('vertical')
function toggle(id:string){opened.value=opened.value.includes(id)?opened.value.filter(x=>x!==id):[...opened.value,id]}
function toggleBoth(){opened.value=opened.value.length===targets.length?[]:targets.map(x=>x.id)}
function reset(){opened.value=[];direction.value='vertical'}
</script>
<template><section class="collapse-usage" aria-label="Collapse usage demonstration"><p>Fictitious local content. Visibility does not fetch or save anything.</p><div class="options"><label>Collapse direction<select v-model="direction"><option>vertical</option><option>horizontal</option></select></label><button type="button" @click="reset">Reset collapse</button></div><div class="actions"><button v-for="item in targets" :id="`collapse-guide-trigger-${item.id}`" :key="item.id" type="button" :aria-controls="`collapse-guide-panel-${item.id}`" :aria-expanded="opened.includes(item.id)" @click="toggle(item.id)">Toggle {{item.label}}</button><button type="button" aria-controls="collapse-guide-panel-delivery collapse-guide-panel-returns" :aria-expanded="opened.length===targets.length" @click="toggleBoth">Toggle both</button></div><div class="panels" :class="direction"><section v-for="item in targets" :id="`collapse-guide-panel-${item.id}`" :key="item.id" :hidden="!opened.includes(item.id)" :aria-labelledby="`collapse-guide-trigger-${item.id}`" class="panel"><h3>{{item.label}} details</h3><p>{{item.body}}</p></section></div><p role="status">{{opened.length}} of 2 sample panels open. Toggle both opens all unless both are already open.</p></section></template>
<style scoped>
.collapse-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options,.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.actions{margin:20px 0}label{display:flex;flex-direction:column;gap:8px}button,select{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}button[aria-expanded=true]{background:var(--vp-c-brand-soft)}button{transition:background 140ms ease-out}.panels{display:flex;flex-direction:column;gap:12px}.panel{min-width:0;padding:16px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.panel h3{margin:0;font-size:17px}.panel p{margin-bottom:0}.panel:not([hidden]){animation:collapse-down 160ms ease-out}.horizontal{flex-direction:row;flex-wrap:wrap}.horizontal .panel{flex:1 1 220px}.horizontal .panel:not([hidden]){animation-name:collapse-across}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:3px}@keyframes collapse-down{from{opacity:.3;translate:0 -4px}to{opacity:1;translate:0 0}}@keyframes collapse-across{from{opacity:.3;translate:-6px 0}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){.panel:not([hidden]){animation:none}button{transition:none}}
</style>
